\label{prop:fox}
$H_2(K_N;k)=\ker\partial_N$ \textup{(}over $k[G/N]$\textup{)}, and
$H_1(K_N)=N/[N,N]$.

\label{lem:compact}
The set $\mathcal G$ of good normal subgroups of $G$ is nonempty and has a minimal
element with respect to inclusion.

\label{lem:initial}
$G(Y_D)$ is free abelian on the $a_i,b_i$, and $x_i=1$ in it. The complex $Y_D$
is Cockcroft, and $D\subset Y_D$ is trivial on $\pi_1$ and zero on $\pi_2$.

\label{lem:structural}
For every presentation $P$ extending $D$,
\begin{equation}\label{eq:generation}
\pi_2(T(P))=\mathbb Z[G(T(P))]\cdot\eta_{P*}\pi_2(P).
\end{equation}
Consequently, if $P$ is Cockcroft then so is $T(P)$, and if $j\colon P\subset P'$ is zero
on $\pi_2$ then so is $T(j)$.

\label{lem:capped-block}
Let $V_q$ be $K(B_q)$ with a $2$-cell attached along each $s_h$ and each $t_h$. Then
$V_q$ is Cockcroft. Consequently the capped presentation of \ref{B3} is Cockcroft.
